static unsigned long long checks,cuts,mutations,cancellations;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"basedetail check %d: %s\n",__LINE__,#x);exit(1);}}while(0)
typedef struct{const uint8_t*data[4];size_t bytes[4];unsigned status;uint8_t projection[32];}Fixture;
#include "basedetail-fixtures.h"
typedef struct{unsigned calls,fail;}Digest;
typedef struct{unsigned calls,stop;}Cancel;
static Digest dg;static Cancel cancel;
static CohStatus digest(void*p,CohBytes b,uint8_t out[32]){Digest*d=p;d->calls++;SHA256(b.data,b.size,out);return d->fail?COH_IO:COH_OK;}
static int poll(void*p){Cancel*c=p;c->calls++;return c->stop&&c->calls==c->stop;}
static CohCostumeImportDigest provider={digest,&dg,sizeof(dg),4096};
static CohBaseDetailInventoryControl control={{poll,&cancel},sizeof(cancel),256};
static CohBaseDetailInventorySources sources;
static CohSalvageDictionary details,details_before;
static CohSalvageWorkspace source_workspace;
static CohBaseDetailInventory out,before,projection,saved;
static CohBaseDetailInventoryWorkspace workspace;
static void reset(void){dg=(Digest){0,0};cancel=(Cancel){0,0};}
static void setup(const Fixture*f){CohSalvageSources s={0};s.provenance=9;for(unsigned i=0;i<3;i++){s.bodies[i]=(CohBytes){f->data[i],f->bytes[i]};SHA256(f->data[i],f->bytes[i],s.expected_sha256[i]);}CohSalvageControl c={0};reset();CHECK(coh_salvage_read(&s,&provider,&c,&details,&source_workspace,COH_SALVAGE_RAM_MAX,0)==COH_OK);memset(&source_workspace,0,sizeof(source_workspace));memset(&sources,0,sizeof(sources));sources.ids=(CohBytes){f->data[3],f->bytes[3]};sources.provenance=9;SHA256(f->data[3],f->bytes[3],sources.expected_ids_sha256);memcpy(sources.expected_details_sha256,details.sha256[2],32);reset();}
static CohStatus read(size_t budget,size_t retained){dg.calls=0;cancel.calls=0;memset(&out,0xa5,sizeof(out));before=out;CohStatus s=coh_basedetail_inventory_read(&sources,&details,&provider,&control,&out,&workspace,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&out,&before,sizeof(out)));return s;}
static void projection_hash(uint8_t hash[32]){projection=out;memset(projection.source_sha256,0,96);memset(projection.ids_sha256,0,32);projection.provenance=0;projection.schema_crc=projection.dependencies=projection.complete=projection.runtime_generation=projection.actor_authority=0;SHA256((const uint8_t*)&projection,sizeof(projection),hash);}
static unsigned fold(unsigned c){return c>='A'&&c<='Z'?c+32:c;}
static int same(CohSalvageText a,CohSalvageText b){if(a.size!=b.size)return 0;for(unsigned i=0;i<a.size;i++)if(fold((unsigned char)out.text[a.offset+i])!=fold((unsigned char)out.text[b.offset+i]))return 0;return 1;}
static CohBytes key(CohSalvageText t){return(CohBytes){(const uint8_t*)out.text+t.offset,t.size};}
static void queries(void){uint32_t row=99999;for(unsigned i=0;i<out.count;i++){CohBaseDetailIdentity*e=&out.entries[i];unsigned first=0;while(!same(e->name,out.entries[first].name))first++;row=99999;CHECK(coh_basedetail_inventory_find(&out,key(e->name),&row)==COH_OK&&row==first);if(!e->active){CHECK(e->id==0);continue;}CHECK(first==i&&e->id&&e->id<out.slot_count);row=99999;CHECK(coh_basedetail_inventory_by_id(&out,e->id,&row)==COH_OK&&row+1==out.slots[e->id]);row=99999;CohStatus status=coh_basedetail_inventory_join(&out,key(e->name),e->id,&row);CHECK(status==(out.slots[e->id]==i+1?COH_OK:COH_NOT_FOUND)&&row==(out.slots[e->id]==i+1?i:99999));}
 for(unsigned i=0;i<out.id_count;i++){CohSalvageIdRow*r=&out.id_rows[i];unsigned first;for(first=0;first<out.id_count;first++)if(out.id_rows[first].id>0&&same(r->name,out.id_rows[first].name))break;row=99999;CHECK(coh_basedetail_inventory_id_find(&out,key(r->name),&row)==(first<out.id_count?COH_OK:COH_NOT_FOUND)&&row==(first<out.id_count?first:99999));first=0;while(first<out.id_count&&(out.id_rows[first].id<=0||out.id_rows[first].id!=r->id))first++;row=99999;CHECK(coh_basedetail_inventory_id_name(&out,(uint32_t)r->id,&row)==(first<out.id_count?COH_OK:COH_NOT_FOUND)&&row==(first<out.id_count?first:99999));}
 for(unsigned i=0;i<out.slot_count;i++){row=99999;CHECK(coh_basedetail_inventory_by_id(&out,i,&row)==(out.slots[i]?COH_OK:COH_NOT_FOUND)&&row==(out.slots[i]?out.slots[i]-1:99999));}row=99999;CHECK(coh_basedetail_inventory_by_id(&out,UINT32_MAX,&row)==COH_NOT_FOUND&&row==99999);CHECK(coh_basedetail_inventory_find(&out,(CohBytes){(const uint8_t*)"not_a_present_detail",20},&row)==COH_NOT_FOUND&&row==99999);CHECK(coh_basedetail_inventory_find(&out,(CohBytes){(const uint8_t*)"x",1},&out.count)==COH_INVALID);}
int main(void){for(unsigned i=0;i<sizeof(fixtures)/sizeof(*fixtures);i++){const Fixture*f=&fixtures[i];setup(f);CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==(CohStatus)f->status);if(f->status){CHECK(!dg.calls);continue;}CHECK(out.complete&&out.provenance==9&&!out.runtime_generation&&!out.actor_authority&&dg.calls==1);CHECK(!memcmp(out.source_sha256,details.sha256,96)&&!memcmp(out.ids_sha256,sources.expected_ids_sha256,32));uint8_t hash[32];projection_hash(hash);CHECK(!memcmp(hash,f->projection,32));queries();}
 const Fixture*f=&fixtures[0];setup(f);CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_OK);CHECK(out.count==1045&&out.id_count==2157&&out.max_id==2157);unsigned polls=cancel.calls;saved=out;details_before=details;
 for(unsigned i=0;i<28;i++){reset();cancel.stop=i<4?i+1:i<24?1+(unsigned)(((uint64_t)polls*(i-3))/21):polls-(27-i);CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_CANCELLED&&cancel.calls==cancel.stop);cancellations++;}reset();dg.fail=1;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_IO&&dg.calls==1);reset();sources.expected_ids_sha256[0]^=1;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_STATE&&dg.calls==1);sources.expected_ids_sha256[0]^=1;reset();
 size_t n=f->bytes[3];uint8_t*copy=malloc(n+1);CHECK(copy);for(unsigned k=0;k<32;k++){sources.ids.size=k<16?k:((n-1)*(k-15))/16;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)!=COH_OK&&!dg.calls);cuts++;}sources.ids.size=n;for(unsigned k=0;k<32;k++){memcpy(copy,f->data[3],n);size_t at=k<16?k:((n-1)*(k-15))/16;copy[at]^=255;sources.ids.data=copy;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)!=COH_OK);reset();mutations++;}memcpy(copy,f->data[3],n);copy[n]=0;sources.ids=(CohBytes){copy,n+1};CHECK(read(COH_BASEDETAIL_RAM_MAX,0)!=COH_OK);sources.ids=(CohBytes){f->data[3],n};reset();
 size_t minimum=COH_BASEDETAIL_STACK_RESERVE+sizeof(sources)+sizeof(details)+sizeof(provider)+sizeof(control)+sizeof(out)+sizeof(workspace)+sizeof(dg)+sizeof(cancel)+provider.scratch_reserve+control.scratch_reserve+n;CHECK(read(minimum,0)==COH_OK);CHECK(read(minimum-1,0)==COH_LIMIT&&!dg.calls);CHECK(read(minimum-sizeof(details),0)==COH_LIMIT);size_t old=6628948u+sizeof(source_workspace);CHECK(read(minimum+old,old)==COH_OK);CHECK(read(minimum+old-1,old)==COH_LIMIT);CHECK(read(COH_BASEDETAIL_RAM_MAX,SIZE_MAX)==COH_LIMIT);provider.scratch_reserve=SIZE_MAX;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_LIMIT);provider.scratch_reserve=4096;control.scratch_reserve=SIZE_MAX;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_LIMIT);control.scratch_reserve=256;reset();
 CHECK(coh_basedetail_inventory_read(&sources,&details,&provider,&control,&out,(CohBaseDetailInventoryWorkspace*)&out,COH_BASEDETAIL_RAM_MAX,0)==COH_INVALID);void*p=provider.context;provider.context=&details;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_INVALID);provider.context=p;size_t bytes=control.context_bytes;control.cancel.context=provider.context;control.context_bytes=provider.context_bytes;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_INVALID);control.cancel.context=&cancel;control.context_bytes=bytes;
 sources.provenance++;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_STATE&&!dg.calls);sources.provenance--;sources.expected_details_sha256[0]^=1;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_STATE&&!dg.calls);sources.expected_details_sha256[0]^=1;
 for(unsigned k=0;k<12;k++){details=details_before;switch(k){case 0:details.complete=0;break;case 1:details.runtime_generation=1;break;case 2:details.schema_crc[0]^=1;break;case 3:details.schema_crc[2]^=1;break;case 4:details.sha256[2][0]^=1;break;case 5:memset(details.sha256[0],0,32);break;case 6:details.details[0].offset=details.text_bytes;break;case 7:details.text[details.details[0].offset+details.details[0].size]=1;break;case 8:details.actor_authority=1;break;case 9:details.complete=2;break;case 10:details.schema_crc[1]^=1;break;default:details.details_count=COH_BASEDETAIL_ROWS_MAX+1;}CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_STATE&&!dg.calls);}details=details_before;reset();memcpy(copy,f->data[3],n);sources.ids.data=copy;CHECK(read(COH_BASEDETAIL_RAM_MAX,0)==COH_OK);CHECK(!memcmp(&out,&saved,sizeof(out)));memset(copy,0,n+1);free(copy);memset(&details,0,sizeof(details));memset(&source_workspace,0,sizeof(source_workspace));memset(&sources,0,sizeof(sources));memset(&provider,0,sizeof(provider));memset(&control,0,sizeof(control));memset(&dg,0,sizeof(dg));memset(&cancel,0,sizeof(cancel));queries();CHECK(!memcmp(&out,&saved,sizeof(out)));
 printf("{\"passed\":true,\"checks\":%llu,\"fixtures\":%zu,\"cuts\":%llu,\"mutations\":%llu,\"cancellations\":%llu,\"authentic_poll_count\":%u,\"owner_bytes\":%zu,\"workspace_bytes\":%zu,\"borrowed_source_owner_bytes\":%zu,\"sources_bytes\":%zu,\"control_bytes\":%zu,\"authentic_minimum_budget\":%zu,\"configured_old_reservation\":%zu,\"reader_heap_allocations\":0,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,sizeof(fixtures)/sizeof(*fixtures),cuts,mutations,cancellations,polls,sizeof(out),sizeof(workspace),sizeof(details),sizeof(sources),sizeof(control),minimum,old);return 0;}
